package vendor.ControllerComponent.Connection;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;

/**
 * Транспортный контейнер для передачи больших файлов.
 *
 * Идея:
 *   Байтовый массив в Java не может быть больше ~2ГБ (ограничение int для длины).
 *   Поэтому большой файл (например, 4ГБ) передаётся не одним byte[], а цепочкой
 *   кусков, каждый из которых не превышает ~2ГБ.
 *
 *   Один экземпляр FileChunk = один кусок файла.
 *   Поле {@code next} указывает на следующий кусок этого же файла,
 *   либо {@code null}, если это последний кусок.
 *
 *   Таким образом формируется односвязный список кусков, описывающий один файл.
 *
 *   Глубина списка (количество кусков) ограничена только доступной оперативкой —
 *   никаких искусственных лимитов на количество вложений нет.
 *
 * Формат куска на проводе (то, что клиент пишет в сокет):
 *   [1 байт: флаг продолжения (1 = есть следующий кусок, 0 = последний)]
 *   [4 байта: длина этого куска]
 *   [N байт: данные куска]
 *
 * Этот класс НИЧЕГО не склеивает сам по себе. Он только переносит данные.
 * Склейка в цельный файл — задача статического метода {@link #mergeAll(FileChunk, String)}.
 *
 * @author User
 */
public class FileChunk {

    /**
     * Данные текущего куска.
     *
     * Размер не может превышать ~2ГБ — это ограничение самого byte[] в Java.
     * Клиент, отправляя большой файл, обязан нарезать его на куски такого размера.
     */
    public final byte[] data;

    /**
     * Ссылка на следующий кусок этого же файла.
     *
     * ВАЖНО: поле НЕ final (в отличие от data).
     * Это нужно для того, чтобы сервер мог читать куски с сокета по одному
     * и постепенно достраивать цепочку: сначала создаётся head, затем
     * к нему дописываются следующие куски через присваивание {@code tail.next = newChunk}.
     *
     * Если бы поле было final, нам пришлось бы сначала прочитать все куски
     * одного файла в список, а потом собирать цепочку с конца — что менее
     * удобно и держит в памяти дополнительную структуру.
     *
     * Значение {@code null} означает, что это последний кусок файла.
     */
    public FileChunk next;

    /**
     * Создаёт кусок с данными.
     * По умолчанию {@code next == null} — то есть кусок считается последним,
     * пока в него явно не будет записана ссылка на продолжение.
     *
     * @param data данные куска. Не должны быть {@code null}.
     */
    public FileChunk(byte[] data) {
        this.data = data;
        this.next = null;
    }

    /**
     * Создаёт кусок с данными и сразу указывает продолжение.
     * Удобно при обратной сборке цепочки (см. вариант B в обсуждении),
     * но в основном сценарии используется конструктор с одним аргументом.
     *
     * @param data данные куска.
     * @param next следующий кусок, либо {@code null}.
     */
    public FileChunk(byte[] data, FileChunk next) {
        this.data = data;
        this.next = next;
    }

    /**
     * @return {@code true}, если у этого куска есть продолжение.
     */
    public boolean hasNext() {
        return next != null;
    }

    /**
     * Сливает все куски цепочки в один файл на диске.
     *
     * Это единственное место, где данные всех кусков объединяются.
     * Метод НЕ собирает весь файл в один byte[] (это невозможно для файлов >2ГБ),
     * а пишет куски последовательно в {@link FileOutputStream}.
     *
     * В памяти в каждый момент времени находится только один кусок.
     * Поэтому метод корректно работает с файлами любого размера — хоть 10ГБ,
     * хоть 100ГБ, лишь бы хватило места на диске.
     *
     * @param head      первый кусок цепочки. Не должен быть {@code null}.
     * @param extension расширение файла (например, "jpg", "bin").
     *                  Может быть {@code null} или пустым — тогда будет ".bin".
     *                  Можно передавать как с точкой (".jpg"), так и без неё ("jpg").
     * @return объект {@link File}, указывающий на собранный файл во временной директории.
     * @throws IOException если не удалось создать или записать файл.
     */
    public static File mergeAll(FileChunk head, String extension) throws IOException {
        if (head == null) {
            throw new IllegalArgumentException("head chunk is null");
        }

        // Нормализуем расширение: приводим к виду ".ext" (с ведущей точкой).
        String suffix;
        if (extension == null || extension.isEmpty()) {
            suffix = ".bin";
        } else if (extension.startsWith(".")) {
            suffix = extension;
        } else {
            suffix = "." + extension;
        }

        // createTempFile создаёт файл в системной временной директории
        // с уникальным именем. Префикс "merged_" — для удобства отладки.
        File output = File.createTempFile("merged_", suffix);

        // try-with-resources гарантирует закрытие потока даже при исключении.
        try (FileOutputStream fos = new FileOutputStream(output)) {
            FileChunk current = head;
            while (current != null) {
                // Пишем кусок целиком. FileOutputStream.write(byte[])
                // пишет все байты массива за один вызов.
                fos.write(current.data);
                current = current.next;
            }
        }

        return output;
    }

    /**
     * Возвращает общий размер всех кусков в байтах.
     *
     * Полезно для логов, проверок и для случаев, когда контроллеру нужно
     * заранее знать полный размер файла, не собирая его.
     *
     * @return суммарная длина данных всех кусков цепочки.
     */
    public long totalSize() {
        long size = 0;
        FileChunk current = this;
        while (current != null) {
            size += current.data.length;
            current = current.next;
        }
        return size;
    }

    /**
     * Возвращает количество кусков в цепочке.
     * Нужно для отладки и диагностики.
     *
     * @return количество узлов, начиная с текущего.
     */
    public int chunkCount() {
        int count = 0;
        FileChunk current = this;
        while (current != null) {
            count++;
            current = current.next;
        }
        return count;
    }
}